static int nc_irq_affinity_path_writable(const char *path)
{
    struct stat st;

    if (!path || stat(path, &st) != 0 || !S_ISREG(st.st_mode))
        return 0;
    /* access(W_OK) is misleading for root on procfs managed-affinity files. */
    return (st.st_mode & (S_IWUSR | S_IWGRP | S_IWOTH)) != 0;
}

static int nc_irq_affinity_any_writable(void)
{
    DIR *dir;
    struct dirent *entry;
    int found = 0;

    dir = opendir("/proc/irq");
    if (!dir)
        return 0;
    while ((entry = readdir(dir)) != NULL) {
        char path[192];
        const char *p = entry->d_name;

        if (!*p)
            continue;
        while (*p && isdigit((unsigned char)*p))
            p++;
        if (*p)
            continue;
        snprintf(path, sizeof(path), "/proc/irq/%s/smp_affinity", entry->d_name);
        if (nc_irq_affinity_path_writable(path)) {
            found = 1;
            break;
        }
    }
    closedir(dir);
    return found;
}

