struct json_object *jmx_vpn_config_apply(struct json_object *cfg)
{
    struct json_object *data=json_object_new_object(), *summary=json_object_new_object(); int dry=nc_json_bool_def(cfg,"dry_run",0);
    if(jmx_netconfig_db_init()!=0){json_object_object_add(data,"ok",json_object_new_boolean(0));return jmx_gen_api_response_data(API_CODE_ERROR,data);} nc_vpn_db_init();
    json_object_object_add(summary,"network_wireguard_interfaces",json_object_new_int(nc_vpn_count_table("vpn_client","WHERE protocol='WireGuard' AND enabled=1")+nc_vpn_count_table("vpn_site","WHERE type='WireGuard' AND enabled=1")));
    json_object_object_add(summary,"openvpn_sections",json_object_new_int(nc_vpn_count_table("vpn_server","WHERE protocol='OpenVPN' AND enabled=1")+nc_vpn_count_table("vpn_client","WHERE protocol='OpenVPN' AND enabled=1")+nc_vpn_count_table("vpn_site","WHERE type='OpenVPN' AND enabled=1")));
    json_object_object_add(summary,"swanctl_conns",json_object_new_int(nc_vpn_count_table("vpn_server","WHERE protocol IN ('IPSec VPN','IKEv2/IPSec') AND enabled=1")+nc_vpn_count_table("vpn_client","WHERE protocol IN ('IPSec VPN','IKEv2/IPSec') AND enabled=1")+nc_vpn_count_table("vpn_site","WHERE type IN ('IPSec VPN','IKEv2/IPSec') AND enabled=1")));
    json_object_object_add(summary,"accounts",json_object_new_int(nc_vpn_count_table("vpn_account","WHERE status='active'")));
    json_object_object_add(summary,"firewall_zone",json_object_new_string("vpn"));
    if(!dry){ FILE *fp=fopen("/etc/config/dreamingwrt_vpn","w"); if(fp){fprintf(fp,"config vpn 'main'\n\toption generated_by 'jmxd'\n\toption updated_at '%lld'\n",(long long)nc_now_s()); fclose(fp);} }
    json_object_object_add(data,"ok",json_object_new_boolean(1));json_object_object_add(data,"dry_run",json_object_new_boolean(dry));json_object_object_add(data,"applied",json_object_new_boolean(!dry));json_object_object_add(data,"summary",summary);return jmx_gen_api_response_data(API_CODE_SUCCESS,data);
}
