/* ── Cellular probe: read runtime info from modem ── */
#define NC_CELLULAR_MMCLI_OUTPUT_MAX (64U * 1024U)
#define NC_CELLULAR_MMCLI_TIMEOUT_MS 5000

static const char *nc_cellular_mmcli_path(void)
{
    static const char *paths[] = { "/usr/bin/mmcli", "/bin/mmcli" };
    size_t i;

    for (i = 0; i < sizeof(paths) / sizeof(paths[0]); i++) {
        if (access(paths[i], X_OK) == 0)
            return paths[i];
    }
    return NULL;
}

static int nc_cellular_mmcli_capture(const char *selector, int sim,
                                     struct jmx_exec_result *result)
{
    const char *path = nc_cellular_mmcli_path();
    char *argv[] = {
        (char *)path, "-K", sim ? "-i" : "-m", (char *)selector, NULL
    };

    if (!path || !result || !jmx_mmcli_selector_ok(selector))
        return -1;
    memset(result, 0, sizeof(*result));
    if (jmx_exec_capture(path, argv, NC_CELLULAR_MMCLI_OUTPUT_MAX,
                         NC_CELLULAR_MMCLI_TIMEOUT_MS, result) != 0)
        return -1;
    if (result->timed_out || result->truncated || result->term_signal != 0 ||
        result->exit_code != 0 || !result->output) {
        jmx_exec_result_free(result);
        return -1;
    }
    return 0;
}

static void nc_cellular_probe_slot(struct json_object *slot)
{
    const char *modem_path = nc_json_str_def(slot, "modem_path", "");
    struct jmx_mmcli_probe probe = {0};
    struct jmx_exec_result result;
    sqlite3_stmt *st = NULL;
    int fields = 0;

    if (!jmx_mmcli_selector_ok(modem_path) ||
        nc_cellular_mmcli_capture(modem_path, 0, &result) != 0)
        return;
    fields = jmx_mmcli_parse_keyvalue(result.output, &probe, 0);
    jmx_exec_result_free(&result);
    if (fields < 0)
        return;

    if (probe.sim_path[0] &&
        nc_cellular_mmcli_capture(probe.sim_path, 1, &result) == 0) {
        int sim_fields = jmx_mmcli_parse_keyvalue(result.output, &probe, 1);
        jmx_exec_result_free(&result);
        if (sim_fields > 0)
            fields += sim_fields;
    }
    if (fields == 0)
        return;

    if (probe.has_signal)
        json_object_object_add(slot, "signal", json_object_new_int(probe.signal));
    if (probe.operator_name[0])
        json_object_object_add(slot, "operator",
                               json_object_new_string(probe.operator_name));
    if (probe.imei[0])
        json_object_object_add(slot, "imei", json_object_new_string(probe.imei));
    if (probe.iccid[0])
        json_object_object_add(slot, "iccid", json_object_new_string(probe.iccid));

    if (nc_exec("BEGIN IMMEDIATE") != 0)
        return;
    if (nc_prepare(&st,
        "UPDATE cellular_slot SET "
        "signal=CASE WHEN ?1 THEN ?2 ELSE signal END,"
        "operator=CASE WHEN ?3<>'' THEN ?3 ELSE operator END,"
        "imei=CASE WHEN ?4<>'' THEN ?4 ELSE imei END,"
        "iccid=CASE WHEN ?5<>'' THEN ?5 ELSE iccid END,"
        "updated_at=?6 WHERE id=?7") != 0)
        goto rollback;
    sqlite3_bind_int(st, 1, probe.has_signal);
    sqlite3_bind_int(st, 2, probe.signal);
    sqlite3_bind_text(st, 3, probe.operator_name, -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, 4, probe.imei, -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, 5, probe.iccid, -1, SQLITE_TRANSIENT);
    sqlite3_bind_int64(st, 6, (sqlite3_int64)nc_now_s());
    sqlite3_bind_text(st, 7, nc_json_str_def(slot, "id", ""), -1,
                      SQLITE_TRANSIENT);
    if (nc_step_done(st) != 0)
        goto rollback;
    sqlite3_finalize(st);
    st = NULL;
    if (nc_exec("COMMIT") == 0)
        return;

rollback:
    if (st)
        sqlite3_finalize(st);
    (void)nc_exec("ROLLBACK");
}

/* ── Cellular service_apply: SQLite → UCI ── */
int jmx_cellular_service_apply(int dry_run)
{
    if (jmx_netconfig_db_init() != 0)
        return -1;
    nc_cellular_db_init();
    if (dry_run)
        return 0;
    /* Probe all enabled slots first */
    sqlite3_stmt *st = NULL;
    if (nc_prepare(&st, "SELECT id,name,modem_path,dev_type,enabled,sim_id,iccid,imei,operator,signal,apn,auth_type,username,password,pincode,network_type,roaming,mTU,dial_num,remark,sort_order,updated_at FROM cellular_slot WHERE enabled=1 ORDER BY sort_order,id") == 0) {
        while (sqlite3_step(st) == SQLITE_ROW) {
            struct json_object *slot = json_object_new_object();
            nc_add_text(slot, "id", st, 0); nc_add_text(slot, "name", st, 1); nc_add_text(slot, "modem_path", st, 2); nc_add_text(slot, "dev_type", st, 3);
            json_object_object_add(slot, "enabled", json_object_new_boolean(sqlite3_column_int(st, 4)));
            nc_add_text(slot, "sim_id", st, 5); nc_add_text(slot, "iccid", st, 6); nc_add_text(slot, "imei", st, 7); nc_add_text(slot, "operator", st, 8);
            json_object_object_add(slot, "signal", json_object_new_int(sqlite3_column_int(st, 9)));
            nc_add_text(slot, "apn", st, 10); nc_add_text(slot, "auth_type", st, 11); nc_add_text(slot, "username", st, 12); nc_add_text(slot, "password", st, 13);
            nc_add_text(slot, "pincode", st, 14); nc_add_text(slot, "network_type", st, 15);
            json_object_object_add(slot, "roaming", json_object_new_boolean(sqlite3_column_int(st, 16)));
            json_object_object_add(slot, "mTU", json_object_new_int(sqlite3_column_int(st, 17)));
            nc_add_text(slot, "dial_num", st, 18); nc_add_text(slot, "remark", st, 19);
            nc_cellular_probe_slot(slot);
            json_object_put(slot);
        }
        sqlite3_finalize(st);
    }
    /* Generate UCI config */
    FILE *fp = fopen("/etc/config/dreamingwrt_cellular", "w");
    if (fp) {
        fprintf(fp, "# generated by jmxd cellular apply\n");
        /* global section */
        if (nc_prepare(&st, "SELECT enabled,default_slot,failover_mode,failover_threshold,probe_interval,probe_host FROM cellular_global WHERE id=1") == 0) {
            if (sqlite3_step(st) == SQLITE_ROW) {
                fprintf(fp, "config cellular 'global'\n\toption enabled '%d'\n\toption default_slot '%s'\n\toption failover_mode '%s'\n\toption failover_threshold '%d'\n\toption probe_interval '%d'\n\toption probe_host '%s'\n\n",
                    sqlite3_column_int(st, 0), (const char*)sqlite3_column_text(st, 1), (const char*)sqlite3_column_text(st, 2),
                    sqlite3_column_int(st, 3), sqlite3_column_int(st, 4), (const char*)sqlite3_column_text(st, 5));
            }
            sqlite3_finalize(st);
        }
        /* slot sections */
        if (nc_prepare(&st, "SELECT id,name,modem_path,dev_type,enabled,apn,auth_type,username,password,pincode,network_type,roaming,mTU,dial_num,remark,sort_order FROM cellular_slot ORDER BY sort_order,id") == 0) {
            while (sqlite3_step(st) == SQLITE_ROW) {
                fprintf(fp, "config slot '%s'\n\toption name '%s'\n\toption modem_path '%s'\n\toption dev_type '%s'\n\toption enabled '%d'\n\toption apn '%s'\n\toption auth_type '%s'\n\toption username '%s'\n\toption password '%s'\n\toption pincode '%s'\n\toption network_type '%s'\n\toption roaming '%d'\n\toption mTU '%d'\n\toption dial_num '%s'\n\toption remark '%s'\n\toption sort_order '%d'\n\n",
                    (const char*)sqlite3_column_text(st, 0), (const char*)sqlite3_column_text(st, 1),
                    (const char*)sqlite3_column_text(st, 2), (const char*)sqlite3_column_text(st, 3),
                    sqlite3_column_int(st, 4), (const char*)sqlite3_column_text(st, 5),
                    (const char*)sqlite3_column_text(st, 6), (const char*)sqlite3_column_text(st, 7),
                    (const char*)sqlite3_column_text(st, 8), (const char*)sqlite3_column_text(st, 9),
                    (const char*)sqlite3_column_text(st, 10), sqlite3_column_int(st, 11),
                    sqlite3_column_int(st, 12), (const char*)sqlite3_column_text(st, 13),
                    (const char*)sqlite3_column_text(st, 14), sqlite3_column_int(st, 15));
            }
            sqlite3_finalize(st);
        }
        fclose(fp);
    }
    return 0;
}

/* ── Wi-Fi config / capabilities ─────────────────────────────────────── */
static void nc_wifi_db_init(void)
{
    nc_exec("CREATE TABLE IF NOT EXISTS wifi_global (id INTEGER PRIMARY KEY CHECK (id = 1),enabled INTEGER NOT NULL DEFAULT 1,country TEXT NOT NULL DEFAULT 'CN',speed_profile TEXT NOT NULL DEFAULT 'conservative',mesh INTEGER NOT NULL DEFAULT 0,auto_link INTEGER NOT NULL DEFAULT 1,band_steering INTEGER NOT NULL DEFAULT 1,fast_roaming INTEGER NOT NULL DEFAULT 1,mlo INTEGER NOT NULL DEFAULT 0,dfs_enabled INTEGER NOT NULL DEFAULT 1,roam_assist INTEGER NOT NULL DEFAULT 0,roam_threshold INTEGER NOT NULL DEFAULT -75,multicast_enhance INTEGER NOT NULL DEFAULT 1,airtime_fairness INTEGER NOT NULL DEFAULT 1,isolated_guest INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL DEFAULT 0)");
    nc_exec("CREATE TABLE IF NOT EXISTS wifi_radios (id TEXT PRIMARY KEY,band TEXT NOT NULL,device TEXT NOT NULL,phy TEXT NOT NULL DEFAULT '',hwmode TEXT NOT NULL DEFAULT '',channel INTEGER NOT NULL DEFAULT 0,width INTEGER NOT NULL DEFAULT 20,htmode TEXT NOT NULL DEFAULT '',txpower INTEGER NOT NULL DEFAULT 0,supported_widths TEXT NOT NULL DEFAULT '',country TEXT NOT NULL DEFAULT '',enabled INTEGER NOT NULL DEFAULT 1,excluded_channels TEXT NOT NULL DEFAULT '',bssid TEXT NOT NULL DEFAULT '',driver TEXT NOT NULL DEFAULT '',virtual_interfaces INTEGER NOT NULL DEFAULT 0,max_vaps INTEGER NOT NULL DEFAULT 8,reserved_vaps INTEGER NOT NULL DEFAULT 1,updated_at INTEGER NOT NULL DEFAULT 0)");
    nc_exec("CREATE TABLE IF NOT EXISTS wifi_ssids (id TEXT PRIMARY KEY,name TEXT NOT NULL,network TEXT NOT NULL DEFAULT 'lan',security TEXT NOT NULL DEFAULT 'WPA3 Personal',encryption TEXT NOT NULL DEFAULT 'sae+ccmp',protocol TEXT NOT NULL DEFAULT 'auto',bands TEXT NOT NULL DEFAULT '2g,5g',enabled INTEGER NOT NULL DEFAULT 1,mlo INTEGER NOT NULL DEFAULT 0,fast_roaming INTEGER NOT NULL DEFAULT 1,ieee80211r INTEGER NOT NULL DEFAULT 0,ieee80211k INTEGER NOT NULL DEFAULT 0,ieee80211v INTEGER NOT NULL DEFAULT 0,rrm INTEGER NOT NULL DEFAULT 0,qbssload INTEGER NOT NULL DEFAULT 0,mobility_domain TEXT NOT NULL DEFAULT '',nasid TEXT NOT NULL DEFAULT '',ft_over_ds INTEGER NOT NULL DEFAULT 1,ft_psk_generate_local INTEGER NOT NULL DEFAULT 1,reassociation_deadline INTEGER NOT NULL DEFAULT 1000,key_rotation INTEGER NOT NULL DEFAULT 0,hidden INTEGER NOT NULL DEFAULT 0,isolate INTEGER NOT NULL DEFAULT 0,pmf TEXT NOT NULL DEFAULT 'optional',vlan TEXT NOT NULL DEFAULT '',remark TEXT NOT NULL DEFAULT '',updated_at INTEGER NOT NULL DEFAULT 0)");
    nc_exec("CREATE TABLE IF NOT EXISTS wifi_speed_limits (id TEXT PRIMARY KEY,name TEXT NOT NULL,download_mbps INTEGER NOT NULL DEFAULT 0,upload_mbps INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL DEFAULT 0)");
    nc_exec("CREATE TABLE IF NOT EXISTS wifi_capabilities (id INTEGER PRIMARY KEY CHECK (id = 1),disabled_func TEXT NOT NULL DEFAULT '',bands TEXT NOT NULL DEFAULT '',max_width INTEGER NOT NULL DEFAULT 160,max_ssids_per_radio INTEGER NOT NULL DEFAULT 8,max_business_ssids_per_radio INTEGER NOT NULL DEFAULT 8,max_ssids_total INTEGER NOT NULL DEFAULT 0,ssid_limit_source TEXT NOT NULL DEFAULT '',updated_at INTEGER NOT NULL DEFAULT 0)");
    nc_exec("INSERT OR IGNORE INTO wifi_global(id) VALUES(1)");
    nc_exec("INSERT OR IGNORE INTO wifi_speed_limits(id,name) VALUES('default','Default')");
    nc_exec("INSERT OR IGNORE INTO wifi_capabilities(id) VALUES(1)");
}

static int nc_has_token(const char *s, const char *tok)
{
    if (!s || !tok || !tok[0]) return 0; size_t n = strlen(tok); const char *p = s;
    while ((p = strstr(p, tok))) { int l = (p == s) || !isalnum((unsigned char)p[-1]); int r = !isalnum((unsigned char)p[n]) && p[n] != '_'; if (l && r) return 1; p += n; }
    /* WIFI blanket covers all WIFI_* sub-items */
    if (!strncmp(tok,"WIFI_",5) && nc_has_token(s,"WIFI")) return 1;
    return 0;
}

static struct json_object *nc_wifi_disabled_func_array(char **raw_out)
{
    FILE *fp = fopen("/etc/disabled_func", "r");
    size_t cap = 512, len = 0; char *buf = calloc(1, cap); char line[256];
    if (fp && buf) {
        while (fgets(line, sizeof(line), fp)) { size_t n = strlen(line); if (len + n + 2 > cap) { cap *= 2; char *nb = realloc(buf, cap); if (!nb) break; buf = nb; } memcpy(buf + len, line, n); len += n; buf[len++] = ' '; buf[len] = 0; }
        fclose(fp);
    } else { if (fp) fclose(fp); if (!buf) buf = strdup(""); }
    struct json_object *arr = json_object_new_array();
    char *work = strdup(buf ? buf : ""), *save = NULL, *tok = strtok_r(work, " \t\r\n,", &save);
    while (tok) { if (tok[0] && tok[0] != '#') json_object_array_add(arr, json_object_new_string(tok)); tok = strtok_r(NULL, " \t\r\n,", &save); }
    free(work); if (raw_out) *raw_out = buf; else free(buf); return arr;
}

static struct json_object *nc_wifi_regdomains(void)
{
    struct json_object *a=json_object_new_array();
    const char *rows[][8]={{"CN","中国","1-13","36-64 / 149-165","普通 Wi-Fi 不开放","1","0","160"},{"US","美国","1-11","36-165","5925-7125 MHz","1","1","320"},{"GB","英国","1-13","36-140","5945-6425 MHz","0","1","320"},{"EU","欧盟","1-13","36-140","5945-6425 MHz","0","1","160"},{"JP","日本","1-14","36-144","5925-6425 MHz","0","1","160"},{"AU","澳大利亚","1-13","36-165","5925-6425 MHz","1","1","160"},{"KR","韩国","1-13","36-165","5925-7125 MHz","1","1","320"},{"SG","新加坡","1-13","36-165","5925-6425 MHz","1","1","160"},{NULL}};
    for(int i=0;rows[i][0];i++){struct json_object*o=json_object_new_object();json_object_object_add(o,"code",json_object_new_string(rows[i][0]));json_object_object_add(o,"name",json_object_new_string(rows[i][1]));json_object_object_add(o,"band24",json_object_new_string(rows[i][2]));json_object_object_add(o,"band5",json_object_new_string(rows[i][3]));json_object_object_add(o,"band6",json_object_new_string(rows[i][4]));json_object_object_add(o,"high5",json_object_new_boolean(atoi(rows[i][5])));json_object_object_add(o,"six",json_object_new_boolean(atoi(rows[i][6])));json_object_object_add(o,"max6",json_object_new_int(atoi(rows[i][7])));json_object_object_add(o,"note",json_object_new_string("final legality is clipped by iw reg get / regdb"));json_object_array_add(a,o);} return a;
}

static int nc_wifi_exec_available(const char *name);
static int nc_wifi_phy_count(void);

static sqlite3_int64 nc_wifi_revision(void)
{
    sqlite3_stmt *st = NULL;
    sqlite3_int64 revision = 0;

    if (nc_prepare(&st,
            "SELECT MAX(updated_at) FROM ("
            "SELECT updated_at FROM wifi_global UNION ALL "
            "SELECT updated_at FROM wifi_radios UNION ALL "
            "SELECT updated_at FROM wifi_ssids UNION ALL "
            "SELECT updated_at FROM wifi_speed_limits UNION ALL "
            "SELECT updated_at FROM wifi_capabilities)") == 0) {
        if (sqlite3_step(st) == SQLITE_ROW)
            revision = sqlite3_column_int64(st, 0);
        sqlite3_finalize(st);
    }
    return revision;
}

static void nc_wifi_add_capability(struct json_object *cap,
                                   struct json_object *reasons,
                                   const char *name, int supported,
                                   const char *reason)
{
    json_object_object_add(cap, name, json_object_new_boolean(supported));
    if (!supported && reasons)
        json_object_object_add(reasons, name,
                               json_object_new_string(reason ? reason : "not_implemented"));
}

static void nc_wifi_build_capabilities(struct json_object *cap, const char *disabled_raw)
{
    sqlite3_stmt *st=NULL; int c2=0,c5=0,c6=0,maxw=0,total=0,maxper=8; char bands[64]="";
    int phy_count = nc_wifi_phy_count();
    int iw_available = nc_wifi_exec_available("iw");
    int iwinfo_available = nc_wifi_exec_available("iwinfo");
    int wifi_cli_available = nc_wifi_exec_available("wifi");
    int uci_available = nc_wifi_exec_available("uci");
    int wifi_available;
    const char *unavailable_reason;
    struct json_object *reasons = json_object_new_object();
    struct json_object *runtime = json_object_new_object();
    if(nc_prepare(&st,"SELECT band,width FROM wifi_radios WHERE enabled=1")==0){while(sqlite3_step(st)==SQLITE_ROW){const char*b=(const char*)sqlite3_column_text(st,0);int w=sqlite3_column_int(st,1);if(!strcmp(b,"2g"))c2=1;else if(!strcmp(b,"5g"))c5=1;else if(!strcmp(b,"6g"))c6=1;if(w>maxw)maxw=w;total++;}sqlite3_finalize(st);} if(maxw==0)maxw=160;
    if(c2)strcat(bands,"2g,"); if(c5)strcat(bands,"5g,"); if(c6)strcat(bands,"6g,"); size_t l=strlen(bands); if(l&&bands[l-1]==',')bands[l-1]=0;
    wifi_available = phy_count > 0 && !nc_has_token(disabled_raw,"WIFI");
    unavailable_reason = nc_has_token(disabled_raw,"WIFI") ? "disabled_by_disabled_func" :
                         (phy_count <= 0 ? "no_phy_detected" : "available");
    json_object_object_add(cap,"wifi",json_object_new_boolean(wifi_available));
    struct json_object *ba=json_object_new_array(); if(wifi_available&&c2&&!nc_has_token(disabled_raw,"WIFI_2G"))json_object_array_add(ba,json_object_new_string("2g")); if(wifi_available&&c5&&!nc_has_token(disabled_raw,"WIFI_5G"))json_object_array_add(ba,json_object_new_string("5g")); if(wifi_available&&c6&&!nc_has_token(disabled_raw,"WIFI_6G"))json_object_array_add(ba,json_object_new_string("6g")); json_object_object_add(cap,"bands",ba);
    json_object_object_add(cap,"high5",json_object_new_boolean(wifi_available&&!nc_has_token(disabled_raw,"WIFI_5G_HIGH")));
    json_object_object_add(cap,"dfs",json_object_new_boolean(wifi_available&&!nc_has_token(disabled_raw,"WIFI_DFS")));
    json_object_object_add(cap,"eht",json_object_new_boolean(wifi_available&&!nc_has_token(disabled_raw,"WIFI_EHT")&&!nc_has_token(disabled_raw,"WIFI_11BE")));
    json_object_object_add(cap,"max_width",json_object_new_int(wifi_available?maxw:0)); json_object_object_add(cap,"width240",json_object_new_boolean(wifi_available&&maxw>=240&&!nc_has_token(disabled_raw,"WIFI_240MHZ"))); json_object_object_add(cap,"width320",json_object_new_boolean(wifi_available&&maxw>=320&&!nc_has_token(disabled_raw,"WIFI_320MHZ")));
    if(nc_prepare(&st,"SELECT MAX(max_vaps),COUNT(*) FROM wifi_radios")==0&&sqlite3_step(st)==SQLITE_ROW){maxper=sqlite3_column_int(st,0);total=sqlite3_column_int(st,1);sqlite3_finalize(st);} if(maxper<=0)maxper=8;
    json_object_object_add(cap,"max_ssids_per_radio",json_object_new_int(wifi_available?maxper:0)); json_object_object_add(cap,"max_business_ssids_per_radio",json_object_new_int(wifi_available?(maxper>1?maxper-1:maxper):0)); json_object_object_add(cap,"max_ssids_total",json_object_new_int(wifi_available?maxper*total:0)); json_object_object_add(cap,"ssid_limit_source",json_object_new_string(!wifi_available?unavailable_reason:(maxper==17?"QCA VAP limit: 16 service SSIDs + 1 primary/control VAP per radio":"fallback/uci discovered"))); json_object_object_add(cap,"source",json_object_new_string("iw phy + uci + /etc/disabled_func"));

    nc_wifi_add_capability(cap, reasons, "read_config", 1, NULL);
    nc_wifi_add_capability(cap, reasons, "runtime_status", iw_available && wifi_available,
                           !wifi_available ? unavailable_reason : "iw_unavailable");
    nc_wifi_add_capability(cap, reasons, "save_config", 0,
                           !wifi_available ? unavailable_reason : "transactional_secret_safe_save_pending");
    nc_wifi_add_capability(cap, reasons, "apply_config", 0,
                           !wifi_available ? unavailable_reason : "transactional_apply_readback_pending");
    nc_wifi_add_capability(cap, reasons, "ssid_create", 0, "resource_crud_pending");
    nc_wifi_add_capability(cap, reasons, "ssid_update", 0, "resource_crud_pending");
    nc_wifi_add_capability(cap, reasons, "ssid_delete", 0, "resource_crud_pending");
    nc_wifi_add_capability(cap, reasons, "radio_update", 0, "transactional_apply_readback_pending");
    nc_wifi_add_capability(cap, reasons, "global_update", 0, "transactional_apply_readback_pending");
    nc_wifi_add_capability(cap, reasons, "speed_limit_create", 0, "resource_crud_pending");
    nc_wifi_add_capability(cap, reasons, "speed_limit_update", 0, "resource_crud_pending");
    nc_wifi_add_capability(cap, reasons, "speed_limit_delete", 0, "resource_crud_pending");
    nc_wifi_add_capability(cap, reasons, "ap_groups", 0, "not_implemented");
    nc_wifi_add_capability(cap, reasons, "ppsk", 0, "not_implemented");
    nc_wifi_add_capability(cap, reasons, "radius_mac_auth", 0, "not_implemented");
    nc_wifi_add_capability(cap, reasons, "schedules", 0, "not_implemented");
    nc_wifi_add_capability(cap, reasons, "mlo", 0, "driver_apply_readback_pending");
    nc_wifi_add_capability(cap, reasons, "scan", 0,
                           "asynchronous_job_lifecycle_pending");
    nc_wifi_add_capability(cap, reasons, "scan_jobs", 0, "asynchronous_job_lifecycle_pending");
    nc_wifi_add_capability(cap, reasons, "airview_realtime", 0, "airview_sampler_pending");
    nc_wifi_add_capability(cap, reasons, "airview_history", 0, "airview_history_store_pending");
    nc_wifi_add_capability(cap, reasons, "websocket", 0, "wifi_topics_pending");

    json_object_object_add(runtime, "phy_count", json_object_new_int(phy_count));
    json_object_object_add(runtime, "iw", json_object_new_boolean(iw_available));
    json_object_object_add(runtime, "iwinfo", json_object_new_boolean(iwinfo_available));
    json_object_object_add(runtime, "wifi_cli", json_object_new_boolean(wifi_cli_available));
    json_object_object_add(runtime, "uci", json_object_new_boolean(uci_available));
    json_object_object_add(runtime, "reason", json_object_new_string(unavailable_reason));
    json_object_object_add(cap, "runtime_dependencies", runtime);
    json_object_object_add(cap, "reasons", reasons);
}

static struct json_object *nc_wifi_rows(const char *kind)
{
    struct json_object *arr=json_object_new_array(); sqlite3_stmt*st=NULL;
    if(!strcmp(kind,"radios")){
        if(nc_prepare(&st,"SELECT id,band,device,phy,hwmode,channel,width,htmode,txpower,supported_widths,country,enabled,excluded_channels,bssid,driver,virtual_interfaces,max_vaps,reserved_vaps FROM wifi_radios ORDER BY id")==0){while(sqlite3_step(st)==SQLITE_ROW){struct json_object*o=json_object_new_object();nc_add_text(o,"id",st,0);nc_add_text(o,"band",st,1);nc_add_text(o,"device",st,2);nc_add_text(o,"phy",st,3);nc_add_text(o,"hwmode",st,4);json_object_object_add(o,"channel",json_object_new_int(sqlite3_column_int(st,5)));json_object_object_add(o,"width",json_object_new_int(sqlite3_column_int(st,6)));nc_add_text(o,"htmode",st,7);json_object_object_add(o,"txpower",json_object_new_int(sqlite3_column_int(st,8)));json_object_object_add(o,"max_txpower",json_object_new_int(sqlite3_column_int(st,8)));json_object_object_add(o,"supported_widths",nc_json_array_from_text((const char*)sqlite3_column_text(st,9)));nc_add_text(o,"country",st,10);json_object_object_add(o,"enabled",json_object_new_boolean(sqlite3_column_int(st,11)));json_object_object_add(o,"excluded_channels",nc_json_array_from_text((const char*)sqlite3_column_text(st,12)));nc_add_text(o,"bssid",st,13);nc_add_text(o,"type",st,14);json_object_object_add(o,"interfaces",json_object_new_int(sqlite3_column_int(st,15)));json_object_object_add(o,"max_vaps",json_object_new_int(sqlite3_column_int(st,16)));json_object_object_add(o,"reserved_vaps",json_object_new_int(sqlite3_column_int(st,17)));json_object_object_add(o,"used_vaps",json_object_new_int(sqlite3_column_int(st,15)));json_object_object_add(o,"clients",json_object_new_int(0));json_object_object_add(o,"utilization",json_object_new_int(0));json_object_object_add(o,"noise",json_object_new_int(0));json_object_object_add(o,"dfs",json_object_new_boolean(strcmp((const char*)sqlite3_column_text(st,1),"5g")==0));json_object_array_add(arr,o);}sqlite3_finalize(st);} }
    else if(!strcmp(kind,"ssids")){
        if(nc_prepare(&st,"SELECT id,name,network,security,encryption,protocol,bands,enabled,mlo,fast_roaming,ieee80211r,ieee80211k,ieee80211v,rrm,qbssload,mobility_domain,nasid,ft_over_ds,ft_psk_generate_local,reassociation_deadline,key_rotation,hidden,isolate,pmf,vlan,remark FROM wifi_ssids ORDER BY id")==0){while(sqlite3_step(st)==SQLITE_ROW){struct json_object*o=json_object_new_object();for(int i=0;i<7;i++){const char*ks[]={"id","name","network","security","encryption","protocol","bands"}; if(i==6)json_object_object_add(o,ks[i],nc_json_array_from_text((const char*)sqlite3_column_text(st,i))); else nc_add_text(o,ks[i],st,i);}json_object_object_add(o,"enabled",json_object_new_boolean(sqlite3_column_int(st,7)));json_object_object_add(o,"mlo",json_object_new_boolean(sqlite3_column_int(st,8)));json_object_object_add(o,"fast_roaming",json_object_new_boolean(sqlite3_column_int(st,9)));json_object_object_add(o,"ieee80211r",json_object_new_boolean(sqlite3_column_int(st,10)));json_object_object_add(o,"ieee80211k",json_object_new_boolean(sqlite3_column_int(st,11)));json_object_object_add(o,"ieee80211v",json_object_new_boolean(sqlite3_column_int(st,12)));json_object_object_add(o,"rrm",json_object_new_boolean(sqlite3_column_int(st,13)));json_object_object_add(o,"qbssload",json_object_new_boolean(sqlite3_column_int(st,14)));nc_add_text(o,"mobility_domain",st,15);nc_add_text(o,"nasid",st,16);json_object_object_add(o,"ft_over_ds",json_object_new_boolean(sqlite3_column_int(st,17)));json_object_object_add(o,"ft_psk_generate_local",json_object_new_boolean(sqlite3_column_int(st,18)));json_object_object_add(o,"reassociation_deadline",json_object_new_int(sqlite3_column_int(st,19)));json_object_object_add(o,"key_rotation",json_object_new_boolean(sqlite3_column_int(st,20)));json_object_object_add(o,"hidden",json_object_new_boolean(sqlite3_column_int(st,21)));json_object_object_add(o,"isolate",json_object_new_boolean(sqlite3_column_int(st,22)));nc_add_text(o,"pmf",st,23);nc_add_text(o,"vlan",st,24);nc_add_text(o,"remark",st,25);json_object_object_add(o,"clients",json_object_new_int(0));json_object_array_add(arr,o);}sqlite3_finalize(st);} }
    else { if(nc_prepare(&st,"SELECT id,name,download_mbps,upload_mbps FROM wifi_speed_limits ORDER BY id")==0){while(sqlite3_step(st)==SQLITE_ROW){struct json_object*o=json_object_new_object();nc_add_text(o,"id",st,0);nc_add_text(o,"name",st,1);json_object_object_add(o,"download_mbps",json_object_new_int(sqlite3_column_int(st,2)));json_object_object_add(o,"upload_mbps",json_object_new_int(sqlite3_column_int(st,3)));json_object_array_add(arr,o);}sqlite3_finalize(st);} }
    return arr;
}

struct json_object *jmx_wifi_config_get(void)
{
    int phy_count;
    if(jmx_netconfig_db_init()!=0)return jmx_gen_api_response_data(API_CODE_ERROR,NULL);
    phy_count = nc_wifi_phy_count();
    char *disabled_raw=NULL; struct json_object *data=json_object_new_object(); json_object_object_add(data,"ts",json_object_new_int64(nc_now_s())); json_object_object_add(data,"generated_at",json_object_new_int64(nc_now_s())); json_object_object_add(data,"contract_version",json_object_new_string("wifi-management.v1")); json_object_object_add(data,"revision",json_object_new_int64(nc_wifi_revision())); json_object_object_add(data,"disabled_func",nc_wifi_disabled_func_array(&disabled_raw)); struct json_object*cap=json_object_new_object(); nc_wifi_build_capabilities(cap,disabled_raw); json_object_object_add(data,"capabilities",cap); json_object_object_add(data,"regdomains",nc_wifi_regdomains());
    sqlite3_stmt*st=NULL; if(nc_prepare(&st,"SELECT enabled,country,speed_profile,mesh,auto_link,band_steering,fast_roaming,mlo,dfs_enabled,roam_assist,roam_threshold,multicast_enhance,airtime_fairness,isolated_guest FROM wifi_global WHERE id=1")==0&&sqlite3_step(st)==SQLITE_ROW){struct json_object*g=json_object_new_object();json_object_object_add(g,"enabled",json_object_new_boolean(sqlite3_column_int(st,0)));nc_add_text(g,"country",st,1);nc_add_text(g,"speed_profile",st,2);json_object_object_add(g,"mesh",json_object_new_boolean(sqlite3_column_int(st,3)));json_object_object_add(g,"auto_link",json_object_new_boolean(sqlite3_column_int(st,4)));json_object_object_add(g,"band_steering",json_object_new_boolean(sqlite3_column_int(st,5)));json_object_object_add(g,"fast_roaming",json_object_new_boolean(sqlite3_column_int(st,6)));json_object_object_add(g,"mlo",json_object_new_boolean(sqlite3_column_int(st,7)));json_object_object_add(g,"dfs_enabled",json_object_new_boolean(sqlite3_column_int(st,8)));json_object_object_add(g,"roam_assist",json_object_new_boolean(sqlite3_column_int(st,9)));json_object_object_add(g,"roam_threshold",json_object_new_int(sqlite3_column_int(st,10)));json_object_object_add(g,"multicast_enhance",json_object_new_boolean(sqlite3_column_int(st,11)));json_object_object_add(g,"airtime_fairness",json_object_new_boolean(sqlite3_column_int(st,12)));json_object_object_add(g,"isolated_guest",json_object_new_boolean(sqlite3_column_int(st,13)));json_object_object_add(data,"global",g);sqlite3_finalize(st);} json_object_object_add(data,"radios",phy_count>0?nc_wifi_rows("radios"):json_object_new_array()); json_object_object_add(data,"ssids",phy_count>0?nc_wifi_rows("ssids"):json_object_new_array()); json_object_object_add(data,"speed_limits",nc_wifi_rows("limits")); free(disabled_raw); return jmx_gen_api_response_data(API_CODE_SUCCESS,data);
}

