static int nc_wifi_write_wireless_draft(void)
{
    FILE*fp=fopen("/etc/config/dreamingwrt_wifi","w"); if(!fp)return -1; sqlite3_stmt*st=NULL; fprintf(fp,"# generated by jmxd; draft source for /etc/config/wireless\n");
    if(nc_prepare(&st,"SELECT id,type,hwmode,channel,htmode,country,txpower,enabled FROM (SELECT id,driver AS type,hwmode,channel,htmode,country,txpower,enabled FROM wifi_radios) ORDER BY id")==0){while(sqlite3_step(st)==SQLITE_ROW){fprintf(fp,"config wifi-device '%s'\n\toption type '%s'\n\toption hwmode '%s'\n\toption channel '%d'\n\toption htmode '%s'\n\toption country '%s'\n\toption txpower '%d'\n\toption disabled '%d'\n\n",(const char*)sqlite3_column_text(st,0),(const char*)sqlite3_column_text(st,1),(const char*)sqlite3_column_text(st,2),sqlite3_column_int(st,3),(const char*)sqlite3_column_text(st,4),(const char*)sqlite3_column_text(st,5),sqlite3_column_int(st,6),sqlite3_column_int(st,7)?0:1);}sqlite3_finalize(st);} 
    if(nc_prepare(&st,"SELECT id,name,network,encryption,enabled,ieee80211r,ieee80211k,ieee80211v,rrm,qbssload,mobility_domain,nasid,ft_over_ds,ft_psk_generate_local,reassociation_deadline,hidden,isolate,pmf,bands FROM wifi_ssids ORDER BY id")==0){while(sqlite3_step(st)==SQLITE_ROW){fprintf(fp,"config wifi-iface '%s'\n\toption mode 'ap'\n\toption ssid '%s'\n\toption network '%s'\n\toption encryption '%s'\n\toption disabled '%d'\n\toption ieee80211r '%d'\n\toption ieee80211k '%d'\n\toption ieee80211v '%d'\n\toption rrm '%d'\n\toption qbssload '%d'\n\toption mobility_domain '%s'\n\toption nasid '%s'\n\toption ft_over_ds '%d'\n\toption ft_psk_generate_local '%d'\n\toption reassociation_deadline '%d'\n\toption hidden '%d'\n\toption isolate '%d'\n\toption ieee80211w '%s'\n\t# bands %s\n\n",(const char*)sqlite3_column_text(st,0),(const char*)sqlite3_column_text(st,1),(const char*)sqlite3_column_text(st,2),(const char*)sqlite3_column_text(st,3),sqlite3_column_int(st,4)?0:1,sqlite3_column_int(st,5),sqlite3_column_int(st,6),sqlite3_column_int(st,7),sqlite3_column_int(st,8),sqlite3_column_int(st,9),(const char*)sqlite3_column_text(st,10),(const char*)sqlite3_column_text(st,11),sqlite3_column_int(st,12),sqlite3_column_int(st,13),sqlite3_column_int(st,14),sqlite3_column_int(st,15),sqlite3_column_int(st,16),(const char*)sqlite3_column_text(st,17),(const char*)sqlite3_column_text(st,18));}sqlite3_finalize(st);} fclose(fp); return 0;
}

/* ── wifi UCI draft writer (guarded) ─────────────────────────────── */
static int nc_wifi_write_uci_draft(void)
{
    /* Write /etc/config/wireless-compatible draft from wifi_ssids + wifi_radios */
    mkdir("/etc/config", 0755);
    FILE *fp = fopen("/etc/config/dreamingwrt_wifi_uci", "w");
    if(!fp) return -1;
    fprintf(fp, "# DreamingWrt wifi UCI draft - auto generated\n# Apply: cp %s /etc/config/wireless && wifi reload\n\n", "/etc/config/dreamingwrt_wifi_uci");

    sqlite3_stmt *st = NULL;
    /* Write radio sections */
    if(nc_prepare(&st, "SELECT id,device,hwmode,channel,htmode,country,txpower,enabled FROM wifi_radios ORDER BY id")==0) {
        while(sqlite3_step(st)==SQLITE_ROW) {
            const char *id = (const char*)sqlite3_column_text(st, 0);
            const char *dev = (const char*)sqlite3_column_text(st, 1);
            const char *hwmode = (const char*)sqlite3_column_text(st, 2);
            int channel = sqlite3_column_int(st, 3);
            const char *htmode = (const char*)sqlite3_column_text(st, 4);
            const char *country = (const char*)sqlite3_column_text(st, 5);
            int txpower = sqlite3_column_int(st, 6);
            int enabled = sqlite3_column_int(st, 7);
            fprintf(fp, "config wifi-device '%s'\n", id);
            fprintf(fp, "\toption type 'mac80211'\n");
            if(hwmode[0]) fprintf(fp, "\toption hwmode '%s'\n", hwmode);
            if(channel > 0) fprintf(fp, "\toption channel '%d'\n", channel);
            if(htmode[0]) fprintf(fp, "\toption htmode '%s'\n", htmode);
            if(country[0]) fprintf(fp, "\toption country '%s'\n", country);
            if(txpower > 0) fprintf(fp, "\toption txpower '%d'\n", txpower);
            if(!enabled) fprintf(fp, "\toption disabled '1'\n");
            fprintf(fp, "\n");
        }
        sqlite3_finalize(st);
    }
    /* Write SSID sections */
    if(nc_prepare(&st, "SELECT id,name,network,encryption,enabled,hidden,isolate,pmf FROM wifi_ssids ORDER BY id")==0) {
        while(sqlite3_step(st)==SQLITE_ROW) {
            const char *id = (const char*)sqlite3_column_text(st, 0);
            const char *name = (const char*)sqlite3_column_text(st, 1);
            const char *network = (const char*)sqlite3_column_text(st, 2);
            const char *enc = (const char*)sqlite3_column_text(st, 3);
            int enabled = sqlite3_column_int(st, 4);
            int hidden = sqlite3_column_int(st, 5);
            int isolate = sqlite3_column_int(st, 6);
            const char *pmf = (const char*)sqlite3_column_text(st, 7);
            fprintf(fp, "config wifi-iface '%s'\n", id);
            fprintf(fp, "\toption device 'radio0'\n");
            fprintf(fp, "\toption mode 'ap'\n");
            fprintf(fp, "\toption ssid '%s'\n", name?name:"");
            if(network[0]) fprintf(fp, "\toption network '%s'\n", network);
            if(enc[0]) fprintf(fp, "\toption encryption '%s'\n", enc);
            if(!enabled) fprintf(fp, "\toption disabled '1'\n");
            if(hidden) fprintf(fp, "\toption hidden '1'\n");
            if(isolate) fprintf(fp, "\toption isolate '1'\n");
            if(pmf[0]) fprintf(fp, "\toption ieee80211w '%s'\n", pmf);
            fprintf(fp, "\n");
        }
        sqlite3_finalize(st);
    }
    fclose(fp);
    return 0;
}

