struct json_object *jmx_lxc_container_config_get(const char *name)
{
    struct json_object *d = json_object_new_object();
    if (!nc_lxc_name_valid(name)) {
        json_object_object_add(d, "ok", json_object_new_boolean(0));
        json_object_object_add(d, "error", json_object_new_string("invalid_name"));
        return jmx_gen_api_response_data(API_CODE_ERROR, d);
    }
    char path[512];
    /* try uci lxcpath first, fallback to /var/lib/lxc */
    char *lxcpath = nc_cmd_output("uci -q get lxc.lxc.lxcpath 2>/dev/null", 256);
    if (lxcpath) { lxcpath[strcspn(lxcpath, "\r\n")] = 0; }
    if (!lxcpath || !lxcpath[0]) { free(lxcpath); lxcpath = strdup("/var/lib/lxc"); }
    snprintf(path, sizeof(path), "%s/%s/config", lxcpath, name);
    free(lxcpath);

    char *content = nc_sys_read_file_text(path, 32768);
    json_object_object_add(d, "ok", json_object_new_boolean(content != NULL));
    json_object_object_add(d, "config", json_object_new_string(content ? content : ""));
    json_object_object_add(d, "config_path", json_object_new_string(path));
    json_object_object_add(d, "ts", json_object_new_int64(nc_now_s()));
    free(content);
    return jmx_gen_api_response_data(API_CODE_SUCCESS, d);
}

